import React from 'react';
import { CityGraph, TrafficLevel } from '../types';

interface Props {
  graph: CityGraph;
  highlightPath: string[];
}

const trafficColors: Record<TrafficLevel, string> = {
  Low: '#4ade80',
  Moderate: '#facc15',
  Heavy: '#fb7185',
  Blocked: '#94a3b8',
};

const GraphVisualization: React.FC<Props> = ({ graph, highlightPath }) => {
  const getNodeColor = (type: string) => {
    switch(type) {
      case 'Ambulance': return '#818cf8';
      case 'Patient': return '#fbbf24';
      case 'Hospital': return '#34d399';
      default: return '#64748b';
    }
  };

  const isEdgeInPath = (from: string, to: string) => {
    for (let i = 0; i < highlightPath.length - 1; i++) {
      if (
        (highlightPath[i] === from && highlightPath[i + 1] === to) ||
        (highlightPath[i] === to && highlightPath[i + 1] === from)
      ) {
        return true;
      }
    }
    return false;
  };

  return (
    <svg width="100%" height="400" viewBox="0 0 1000 600" style={{ background: 'linear-gradient(135deg, rgba(30, 41, 59, 0.6) 0%, rgba(15, 23, 42, 0.8) 100%)', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.1)' }}>
      {/* Background grid pattern */}
      <defs>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="rgba(255,255,255,0.03)" strokeWidth="1"/>
        </pattern>
        <filter id="glow">
          <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
          <feMerge>
            <feMergeNode in="coloredBlur"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>
      </defs>
      <rect width="100%" height="100%" fill="url(#grid)" />

      {/* Edges */}
      {graph.edges.map((edge, idx) => {
        const fromNode = graph.nodes.find(n => n.id === edge.from)!;
        const toNode = graph.nodes.find(n => n.id === edge.to)!;
        const inPath = isEdgeInPath(edge.from, edge.to);

        return (
          <g key={idx}>
            {/* Glow effect for selected path */}
            {inPath && (
              <line
                x1={fromNode.x}
                y1={fromNode.y}
                x2={toNode.x}
                y2={toNode.y}
                stroke="#818cf8"
                strokeWidth={12}
                strokeLinecap="round"
                opacity="0.3"
                filter="url(#glow)"
              />
            )}
            <line
              x1={fromNode.x}
              y1={fromNode.y}
              x2={toNode.x}
              y2={toNode.y}
              stroke={inPath ? '#c7d2fe' : trafficColors[edge.traffic]}
              strokeWidth={inPath ? 4 : 2}
              strokeDasharray={edge.traffic === 'Blocked' ? '8,8' : '0'}
              strokeLinecap="round"
              style={{
                transition: 'all 0.3s ease',
                opacity: inPath ? 1 : 0.5
              }}
            />
          </g>
        );
      })}
      {/* Nodes */}
      {graph.nodes.map(node => (
        <g key={node.id}>
          {/* Outer glow */}
          <circle
            cx={node.x}
            cy={node.y}
            r={32}
            fill={getNodeColor(node.type)}
            opacity="0.2"
            filter="url(#glow)"
          />
          {/* Main circle */}
          <circle
            cx={node.x}
            cy={node.y}
            r={26}
            fill={getNodeColor(node.type)}
            style={{
              filter: 'drop-shadow(0 4px 12px rgba(0,0,0,0.4))',
              transition: 'all 0.3s ease'
            }}
          />
          {/* Inner ring */}
          <circle
            cx={node.x}
            cy={node.y}
            r={22}
            fill="none"
            stroke="rgba(255,255,255,0.3)"
            strokeWidth="2"
          />
          {/* Node ID */}
          <text x={node.x} y={node.y + 5} textAnchor="middle" fill="white" fontSize="15" fontWeight="600" fontFamily="Inter" style={{ textShadow: '0 1px 3px rgba(0,0,0,0.3)' }}>
            {node.id}
          </text>
          {/* Node name */}
          <text x={node.x} y={node.y + 48} textAnchor="middle" fill="#cbd5e1" fontSize="12" fontWeight="500" fontFamily="Inter" style={{ textShadow: '0 1px 2px rgba(0,0,0,0.5)' }}>
            {node.name}
          </text>
        </g>
      ))}
      {/* Legend */}
      <g transform="translate(20, 20)">
        <rect x="0" y="0" width="140" height="115" fill="rgba(15, 23, 42, 0.95)" rx="10" stroke="rgba(255,255,255,0.1)" strokeWidth="1" />
        <text x="14" y="24" fontSize="11" fontWeight="600" fill="#e2e8f0">Node Types</text>
        <circle cx="20" cy="45" r="7" fill="#818cf8" opacity="0.9" />
        <text x="35" y="49" fontSize="10" fill="#94a3b8">Start</text>
        <circle cx="20" cy="65" r="7" fill="#fbbf24" opacity="0.9" />
        <text x="35" y="69" fontSize="10" fill="#94a3b8">Patient</text>
        <circle cx="20" cy="85" r="7" fill="#4ade80" opacity="0.9" />
        <text x="35" y="89" fontSize="10" fill="#94a3b8">Hospital</text>
        <circle cx="20" cy="105" r="7" fill="#64748b" opacity="0.9" />
        <text x="35" y="109" fontSize="10" fill="#94a3b8">Normal</text>
      </g>
      {/* Traffic Legend */}
      <g transform="translate(840, 20)">
        <rect x="0" y="0" width="140" height="110" fill="rgba(15, 23, 42, 0.95)" rx="10" stroke="rgba(255,255,255,0.1)" strokeWidth="1" />
        <text x="14" y="24" fontSize="11" fontWeight="600" fill="#e2e8f0">Traffic Levels</text>
        <line x1="16" y1="42" x2="34" y2="42" stroke="#4ade80" strokeWidth="2.5" strokeLinecap="round" />
        <text x="42" y="46" fontSize="10" fill="#94a3b8">Low</text>
        <line x1="16" y1="62" x2="34" y2="62" stroke="#facc15" strokeWidth="2.5" strokeLinecap="round" />
        <text x="42" y="66" fontSize="10" fill="#94a3b8">Moderate</text>
        <line x1="16" y1="82" x2="34" y2="82" stroke="#fb7185" strokeWidth="2.5" strokeLinecap="round" />
        <text x="42" y="86" fontSize="10" fill="#94a3b8">Heavy</text>
        <line x1="16" y1="102" x2="34" y2="102" stroke="#94a3b8" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="4,4" />
        <text x="42" y="106" fontSize="10" fill="#94a3b8">Blocked</text>
      </g>
    </svg>
  );
};

export default GraphVisualization;
